# frozen_string_literal: true

# Rebuild the lab's generated pages after every LOCAL build, so they cannot go stale:
# the workbench (every component as a real element from a real page) and the code-audit pages
# (one page per source file, listed in the lab to-do page).
#
# Both generators read the built site and the source, so the only moment their output can be
# right is straight after a build. The first workbench was generated by hand on 2026-09-04 and
# was three weeks behind the site when it was checked (docs/WORKBENCH-CHECK.md).
#
# ONLY UNDER `jekyll serve`. The deploy runs `jekyll build`, where this does nothing: everything
# here lands in `_site/redesign-lab/`, which the deploy deletes before upload anyway
# (.github/workflows/pages-deploy.yml:68), and the deploy should not need Python.
#
# They write into `_site/`, never the source tree. Writing into the source would make Jekyll see
# a change and build again, which would run this again.
Jekyll::Hooks.register :site, :post_write do |site|
  next unless site.config['serving']

  %w[build_workbench.py build_audit.py].each do |tool|
    built = system('python', File.join(site.source, 'tools', tool), '--quiet')
    Jekyll.logger.warn 'Lab pages:', "#{tool} did not run (is Python installed?)" unless built
  end
end
